/// How a layout presents its nav on a phone.
enum CruftFreeNavIdiom { bottomBar, drawer }

/// One entry of a layout's nav, as the shared nav plan holds it: a page link
/// ([CruftFreeNavLink]), a link leaving the app ([CruftFreeNavExternal]), or a section of
/// them ([CruftFreeNavSection]).
sealed class CruftFreeNavEntry {
  const CruftFreeNavEntry();

  String get label;

  IconData? get icon;

  /// Whether the session may see it -- UX only, the server authorizes every request.
  bool get visible;

  /// Whether activating it opens a new tab: its name then carries the framework's words for it.
  bool get opensNewTab => false;
}

/// One nav link: its route, its label, and what it shows beside the label.
class CruftFreeNavLink extends CruftFreeNavEntry {
  const CruftFreeNavLink({required this.path, required this.label, this.icon, this.visible = true, this.badge});

  final String path;
  @override
  final String label;
  @override
  final IconData? icon;
  @override
  final bool visible;
  final String? badge;
}

/// A nav `externalLink`: activating it opens [address] through the checked
/// [openExternalLink], which opens nothing for an address a user may not be
/// sent to -- in place, or in a new browsing context when [newTab] holds.
class CruftFreeNavExternal extends CruftFreeNavEntry {
  const CruftFreeNavExternal({required this.label, required this.address, required this.newTab, this.icon});

  @override
  final String label;
  final Object? address;
  final bool newTab;
  @override
  final IconData? icon;

  @override
  bool get visible => true;

  @override
  bool get opensNewTab => newTab;
}

/// A nav `section`: its title and its entries under their group headings.
/// It is shown while one of its entries is, and active while one of its page
/// links is the current route.
class CruftFreeNavSection extends CruftFreeNavEntry {
  const CruftFreeNavSection({required this.label, this.icon, required this.groups});

  @override
  final String label;
  @override
  final IconData? icon;
  final List<CruftFreeNavGroup> groups;

  /// Its entries the session may see, in order.
  List<CruftFreeNavEntry> get shown => [
    for (final group in groups)
      for (final entry in group.entries)
        if (entry.visible) entry,
  ];

  @override
  bool get visible => shown.isNotEmpty;

  /// Whether the route at [location] is one of its page links.
  bool activeAt(String location) => shown.any((entry) => entry is CruftFreeNavLink && entry.path == location);
}

/// A run of consecutive nav entries under one heading; [heading] is null for
/// a run of entries that declare none.
class CruftFreeNavGroup {
  const CruftFreeNavGroup({this.heading, required this.entries});

  final String? heading;
  final List<CruftFreeNavEntry> entries;
}

const IconData _defaultNavIcon = Icons.circle_outlined;
const double _headingSize = 10;

Widget _navIcon(CruftFreeNavEntry entry) {
  final icon = Icon(entry.icon ?? _defaultNavIcon);
  final badge = entry is CruftFreeNavLink ? entry.badge : null;
  return badge == null || badge.isEmpty ? icon : Badge(label: Text(badge), child: icon);
}

/// [entry]'s label as a widget: the text, and for an entry that opens a new tab the framework's
/// words as its semantics hint and, while the theme draws one, the glyph after it.
Widget _navLabel(BuildContext context, CruftFreeNavEntry entry) {
  if (!entry.opensNewTab) {
    return Text(entry.label);
  }
  final glyph = cruftfreeNewTabGlyph(context);
  return Semantics(
    hint: cruftfreeNewTabWords(),
    child: Row(mainAxisSize: MainAxisSize.min, spacing: CruftFreeTokens.of(context).gap / 2, children: [Text(entry.label), ?glyph]),
  );
}

/// [entry]'s label as a tooltip: its words for assistive technology after it when it opens a new tab.
String _navTooltip(CruftFreeNavEntry entry) => entry.opensNewTab ? '${entry.label}: ${cruftfreeNewTabWords()}' : entry.label;

/// Opens [entry] -- a page link's route, an external link's checked address --
/// closing the drawer it was activated in first when [closeDrawer] holds.
void _openNavEntry(BuildContext context, CruftFreeNavEntry entry, {required bool closeDrawer}) {
  if (closeDrawer) {
    Navigator.of(context).pop();
  }
  switch (entry) {
    case CruftFreeNavLink(:final path):
      GoRouter.of(context).go(path);
    case CruftFreeNavExternal(:final address, :final newTab):
      openExternalLink(address, newTab: newTab);
    case CruftFreeNavSection():
      break;
  }
}

Widget _heading(BuildContext context, String heading) {
  final theme = Theme.of(context);
  final tokens = CruftFreeTokens.of(context);
  return Semantics(
    header: true,
    child: Padding(
      padding: EdgeInsets.fromLTRB(tokens.inset, tokens.inset, tokens.inset, tokens.gap / 2),
      child: Text(
        heading.toUpperCase(),
        style: theme.textTheme.labelSmall?.copyWith(fontSize: _headingSize, color: theme.colorScheme.onSurfaceVariant),
      ),
    ),
  );
}

/// How a vertical nav draws its entries: the persistent sidebar panel (a
/// section's title is a heading above its links), its icon-only form (a
/// divider stands for every heading), or a drawer (a section is an accordion
/// row, open while it is active).
enum _NavRows { panel, collapsed, drawer }

List<Widget> _entries(BuildContext context, List<CruftFreeNavGroup> groups, String location, _NavRows mode) {
  final entries = <Widget>[];
  final collapsed = mode == _NavRows.collapsed;
  for (final group in groups) {
    final shown = group.entries.where((entry) => entry.visible).toList();
    final heading = group.heading;
    if (shown.isEmpty) {
      continue;
    }
    if (heading != null) {
      entries.add(collapsed ? const Divider() : _heading(context, heading));
    }
    for (final entry in shown) {
      entries.addAll(_entryRows(context, entry, location, mode));
    }
  }
  return entries;
}

List<Widget> _entryRows(BuildContext context, CruftFreeNavEntry entry, String location, _NavRows mode) {
  if (entry is! CruftFreeNavSection) {
    return [_leaf(context, entry, location, mode)];
  }
  final rows = _entries(context, entry.groups, location, mode);
  return switch (mode) {
    _NavRows.panel => [_heading(context, entry.label), ...rows],
    _NavRows.collapsed => [const Divider(), ...rows],
    _NavRows.drawer => [_accordion(context, entry, location, rows)],
  };
}

/// A section in a drawer: a row opening its entries in place, open from the
/// start while the section is active.
Widget _accordion(BuildContext context, CruftFreeNavSection section, String location, List<Widget> rows) {
  final active = section.activeAt(location);
  final scheme = Theme.of(context).colorScheme;
  return ExpansionTile(
    leading: Icon(section.icon ?? _defaultNavIcon),
    title: Text(section.label),
    initiallyExpanded: active,
    collapsedTextColor: active ? scheme.primary : null,
    collapsedIconColor: active ? scheme.primary : null,
    childrenPadding: EdgeInsetsDirectional.only(start: CruftFreeTokens.of(context).inset),
    children: rows,
  );
}

Widget _leaf(BuildContext context, CruftFreeNavEntry entry, String location, _NavRows mode) {
  final selected = entry is CruftFreeNavLink && entry.path == location;
  final closeDrawer = mode == _NavRows.drawer;
  if (mode == _NavRows.collapsed) {
    return Tooltip(
      message: _navTooltip(entry),
      child: IconButton(
        isSelected: selected,
        icon: _navIcon(entry),
        onPressed: () => _openNavEntry(context, entry, closeDrawer: closeDrawer),
      ),
    );
  }
  return ListTile(
    leading: _navIcon(entry),
    title: _navLabel(context, entry),
    selected: selected,
    onTap: () => _openNavEntry(context, entry, closeDrawer: closeDrawer),
  );
}

/// Whether [shown] fits a bottom navigation bar: two entries or more, none a section.
bool _fitsBottomBar(List<CruftFreeNavEntry> shown) => shown.length >= 2 && shown.every((entry) => entry is! CruftFreeNavSection);

Widget _bottomNavigation(BuildContext context, List<CruftFreeNavEntry> shown, String location) {
  final selected = shown.indexWhere((entry) => entry is CruftFreeNavLink && entry.path == location);
  return NavigationBar(
    selectedIndex: selected < 0 ? 0 : selected,
    onDestinationSelected: (index) => _openNavEntry(context, shown[index], closeDrawer: false),
    destinations: [for (final entry in shown) NavigationDestination(icon: _navIcon(entry), label: entry.label, tooltip: _navTooltip(entry))],
  );
}

