/// The routed page's region in a layout that offers a skip link ([CruftFreeSkipLink]): focusable by the
/// link alone, never a tab stop of its own. Outside such a layout it draws [child] as it is.
class CruftFreeSkipTarget extends StatelessWidget {
  const CruftFreeSkipTarget({super.key, required this.child});

  final Widget child;

  @override
  Widget build(BuildContext context) {
    final scope = context.dependOnInheritedWidgetOfExactType<_CruftFreeSkipScope>();
    if (scope == null) {
      return child;
    }
    return Focus(focusNode: scope.content, child: child);
  }
}

/// A layout's skip link: the first control in focus order, drawn only while it holds keyboard
/// focus (transparent, ignoring pointers and taking no space from [child] the rest of the time, yet
/// still read out by assistive technology). Activating it puts focus on the first control of the
/// content ([CruftFreeSkipTarget]), or on the region itself when it holds none.
class CruftFreeSkipLink extends StatefulWidget {
  const CruftFreeSkipLink({super.key, required this.child});

  final Widget child;

  @override
  State<CruftFreeSkipLink> createState() => _CruftFreeSkipLinkState();
}

class _CruftFreeSkipLinkState extends State<CruftFreeSkipLink> {
  final FocusNode _link = FocusNode(debugLabel: 'skip link');
  final FocusNode _content = FocusNode(skipTraversal: true, debugLabel: 'content');
  bool _shown = false;

  @override
  void initState() {
    super.initState();
    _link.addListener(_track);
  }

  @override
  void dispose() {
    _link.dispose();
    _content.dispose();
    super.dispose();
  }

  void _track() {
    if (_link.hasFocus != _shown) {
      setState(() => _shown = _link.hasFocus);
    }
  }

  void _skip() {
    final controls = _content.descendants.where((node) => node.canRequestFocus && !node.skipTraversal);
    (controls.isEmpty ? _content : controls.first).requestFocus();
  }

  @override
  Widget build(BuildContext context) {
    return _CruftFreeSkipScope(
      content: _content,
      child: Stack(
        fit: StackFit.expand,
        children: [
          widget.child,
          PositionedDirectional(
            top: 0,
            start: 0,
            child: IgnorePointer(
              ignoring: !_shown,
              child: Opacity(
                opacity: _shown ? 1 : 0,
                child: FilledButton(focusNode: _link, onPressed: _skip, child: Text(cruftfreeSkipLinkWords())),
              ),
            ),
          ),
        ],
      ),
    );
  }
}

/// A layout: its view, with its nav as a bottom navigation bar or a drawer.
class CruftFreeLayoutScaffold extends StatelessWidget {
  const CruftFreeLayoutScaffold({super.key, required this.idiom, required this.links, this.footer = const <Widget>[], required this.body});

  final CruftFreeNavIdiom idiom;
  final List<CruftFreeNavEntry> links;
  final List<Widget> footer;
  final Widget body;

  @override
  Widget build(BuildContext context) {
    final shown = links.where((link) => link.visible).toList();
    final location = GoRouter.of(context).routeInformationProvider.value.uri.path;
    final content = CruftFreeLayoutBody(footer: footer, child: body);
    if (idiom == CruftFreeNavIdiom.bottomBar && _fitsBottomBar(shown)) {
      return Scaffold(body: content, bottomNavigationBar: _bottomNavigation(context, shown, location));
    }
    return Scaffold(
      appBar: AppBar(),
      drawer: Drawer(
        child: SafeArea(
          child: ListView(children: _entries(context, [CruftFreeNavGroup(entries: links)], location, _NavRows.drawer)),
        ),
      ),
      body: content,
    );
  }
}

