  final List<CruftFreeNavGroup> groups;
  final String location;

  @override
  bool updateShouldNotify(_CruftFreeNavBarScope oldWidget) => oldWidget.groups != groups || oldWidget.location != location;
}

/// A `nav;` in a layout's top bar: the layout's nav as a row of the app bar --
/// its links as buttons, the current one marked, and each section a
/// [CruftFreeNavDropdown] -- while the scaffold draws the nav there (a window at
/// least its `navBarFrom` wide); nothing otherwise, the drawer holding the
/// nav then.
class CruftFreeNavBar extends StatelessWidget {
  const CruftFreeNavBar({super.key});

  @override
  Widget build(BuildContext context) {
    final scope = context.dependOnInheritedWidgetOfExactType<_CruftFreeNavBarScope>();
    if (scope == null) {
      return const SizedBox.shrink();
    }
    final location = scope.location;
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        for (final group in scope.groups)
          for (final entry in group.entries)
            if (entry is CruftFreeNavSection && entry.visible) CruftFreeNavDropdown(section: entry, location: location) else if (entry.visible) _CruftFreeNavBarButton(entry: entry, selected: entry is CruftFreeNavLink && entry.path == location, onPressed: () => _openNavEntry(context, entry, closeDrawer: false)),
      ],
    );
  }
}

/// One entry of the app bar's nav row: its icon, when it declares one, and its label.
class _CruftFreeNavBarButton extends StatelessWidget {
  const _CruftFreeNavBarButton({required this.entry, required this.selected, required this.onPressed, this.focusNode, this.trailing});

  final CruftFreeNavEntry entry;
  final bool selected;
  final VoidCallback onPressed;
  final FocusNode? focusNode;
  final Widget? trailing;

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    final gap = CruftFreeTokens.of(context).gap / 2;
    return Semantics(
      selected: selected,
      child: TextButton(
        focusNode: focusNode,
        onPressed: onPressed,
        style: TextButton.styleFrom(foregroundColor: selected ? scheme.primary : scheme.onSurface),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            if (entry.icon != null) ...[_navIcon(entry), SizedBox(width: gap)],
            _navLabel(context, entry),
            ?trailing,
          ],
        ),
      ),
    );
  }
}

/// The entry to focus after [key] when entry [current] of [count] has focus
/// (`-1` for none), or `-1` when the key moves nothing -- the menu-keys model
/// every client target answers: ArrowDown and ArrowUp wrap, Home and End
/// reach the ends, and a panel with no entry moves nowhere.
int cruftfreeMenuKeyIndex(int count, int current, String key) {
  if (count == 0) {
    return -1;
  }
  if (key == 'ArrowDown') {
    return (current + 1) % count;
  }
  if (key == 'ArrowUp') {
    return current <= 0 ? count - 1 : current - 1;
  }
  if (key == 'Home') {
    return 0;
  }
  if (key == 'End') {
    return count - 1;
  }
  return -1;
}

/// Whether [key] closes a panel and returns focus to the control that opened it.
bool cruftfreeMenuKeyCloses(String key) => key == 'Escape';

/// The keyboard key behind each key name the menu-keys model answers.
final Map<LogicalKeyboardKey, String> _menuKeyNames = <LogicalKeyboardKey, String>{LogicalKeyboardKey.arrowDown: 'ArrowDown', LogicalKeyboardKey.arrowUp: 'ArrowUp', LogicalKeyboardKey.home: 'Home', LogicalKeyboardKey.end: 'End', LogicalKeyboardKey.escape: 'Escape'};

/// A nav `section` in a top bar: a dropdown of its entries under their group
/// headings, its control marked while the section is active (one of its page
/// links is the current route). A mouse resting on the control opens it
/// without moving focus, and leaving the control and the panel closes it
/// again unless the control was used; activating the control toggles it and
/// moves focus to its first entry; while it is open the arrow keys, Home and
/// End move focus as [cruftfreeMenuKeyIndex] says, Escape closes it and returns
/// focus to the control, and a tap outside closes it.
class CruftFreeNavDropdown extends StatefulWidget {
  const CruftFreeNavDropdown({super.key, required this.section, required this.location});

  final CruftFreeNavSection section;
  final String location;

  @override
  State<CruftFreeNavDropdown> createState() => _CruftFreeNavDropdownState();
}

class _CruftFreeNavDropdownState extends State<CruftFreeNavDropdown> {
  final MenuController _controller = MenuController();
  final FocusNode _control = FocusNode(debugLabel: 'nav section control');
  final List<FocusNode> _items = [];
  bool _openedByHover = false;
  bool _controlUsed = false;
  bool _overControl = false;
  bool _overPanel = false;

  @override
  void dispose() {
    _control.dispose();
    for (final item in _items) {
      item.dispose();
    }
    super.dispose();
  }

  FocusNode _item(int index) {
    while (_items.length <= index) {
      _items.add(FocusNode(debugLabel: 'nav section entry ${_items.length}'));
    }
    return _items[index];
  }

  int get _count => widget.section.shown.length;

  /// Rebuilds once the frame the menu opened or closed in is done.
  void _refresh() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) {
        setState(() {});
      }
    });
  }

  void _toggle() {
    final pinsHoverOpen = _controller.isOpen && _openedByHover && !_controlUsed;
    _controlUsed = true;
    if (_controller.isOpen && !pinsHoverOpen) {
      _controller.close();
      return;
    }
    _controller.open();
    if (_count > 0) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && _controller.isOpen) {
          _item(0).requestFocus();
        }
      });
    }
  }

  void _hover(PointerEvent event, {required bool control, required bool inside}) {
    if (event.kind != PointerDeviceKind.mouse) {
      return;
    }
    if (control) {
      _overControl = inside;
    } else {
      _overPanel = inside;
    }
    if (inside) {
      if (!_controller.isOpen) {
        _openedByHover = true;
        _controller.open();
      }
      return;
    }
    // Moving from the control into the panel leaves one and enters the other in one pointer update.
    scheduleMicrotask(() {
      if (mounted && _openedByHover && !_controlUsed && !_overControl && !_overPanel && _controller.isOpen) {
        _controller.close();
      }
    });
  }

  KeyEventResult _onKey(FocusNode node, KeyEvent event) {
    if (!_controller.isOpen || (event is! KeyDownEvent && event is! KeyRepeatEvent)) {
      return KeyEventResult.ignored;
    }
    final key = _menuKeyNames[event.logicalKey];
    if (key == null) {
      return KeyEventResult.ignored;
    }
    if (cruftfreeMenuKeyCloses(key)) {
      _controller.close();
      _control.requestFocus();
      return KeyEventResult.handled;
    }
    final count = _count;
    final current = _items.take(count).toList().indexWhere((item) => item.hasFocus);
    final next = cruftfreeMenuKeyIndex(count, current, key);
    if (next >= 0) {
      _item(next).requestFocus();
    }
    return KeyEventResult.handled;
  }

  List<Widget> _rows(BuildContext context) {
    final rows = <Widget>[];
    var index = 0;
    for (final group in widget.section.groups) {
      final shown = group.entries.where((entry) => entry.visible).toList();
      final heading = group.heading;
      if (shown.isEmpty) {
        continue;
      }
      if (heading != null) {
        rows.add(_heading(context, heading));
      }
      for (final entry in shown) {
        rows.add(
          Semantics(
            selected: entry is CruftFreeNavLink && entry.path == widget.location,
            child: MenuItemButton(focusNode: _item(index), leadingIcon: entry.icon == null ? null : _navIcon(entry), onPressed: () => _openNavEntry(context, entry, closeDrawer: false), child: _navLabel(context, entry)),
          ),
        );
        index += 1;
      }
    }
    return rows;
  }

  @override
  Widget build(BuildContext context) {
    final open = _controller.isOpen;
    return MenuAnchor(
      controller: _controller,
      onOpen: _refresh,
      onClose: () {
        _openedByHover = false;
        _controlUsed = false;
        _refresh();
      },
      menuChildren: [
        MouseRegion(
          onEnter: (event) => _hover(event, control: false, inside: true),
          onExit: (event) => _hover(event, control: false, inside: false),
          child: Focus(
            canRequestFocus: false,
            skipTraversal: true,
            onKeyEvent: _onKey,
            child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: _rows(context)),
          ),
        ),
      ],
      child: MouseRegion(
        onEnter: (event) => _hover(event, control: true, inside: true),
        onExit: (event) => _hover(event, control: true, inside: false),
        child: Focus(
          canRequestFocus: false,
          skipTraversal: true,
          onKeyEvent: _onKey,
          child: Semantics(
            expanded: open,
            child: _CruftFreeNavBarButton(entry: widget.section, selected: widget.section.activeAt(widget.location), focusNode: _control, onPressed: _toggle, trailing: Icon(open ? Icons.expand_less : Icons.expand_more)),
          ),
        ),
      ),
    );
  }
}

/// A layout that declares an app shell: a `sidebar`, a `topBar`, or both.
///
/// With a [sidebar], the sidebar is a persistent panel at and above
/// [sidebarBreakpoint] (256 logical pixels wide, or 64 and icon-only while
/// [collapsed] holds true) and the content of a drawer, opened from the app
/// bar's menu button, below it. Nav entries render under their group headings
/// and a section's title (a divider replaces the headings while the panel is
/// icon-only; a section is an accordion row in the drawer). A non-null
/// [collapsed] makes the panel collapsible, and the user's choice is kept in
/// it. Without a sidebar the nav follows [idiom], as a layout without a shell
/// does. The [topBar] widgets render in the app bar: the first as its title,
/// the rest as its actions. A non-null [navBarFrom] says the layout's `nav;`
/// sits in its top bar: on a window at least that wide the app bar draws the
/// nav there ([CruftFreeNavBar], each section a dropdown) and neither the panel nor
/// the drawer repeats it. The app bar's colour runs the full width; its
/// content lines up with the content column ([CruftFreeContentColumn]) unless
/// [topBarFullWidth]. The app bar stays in view while the page scrolls only
/// with [topBarSticky] (the scaffold's own app bar); otherwise it is the first
/// thing in the layout's scrolling body ([CruftFreeLayoutBody.scrollingBar]) and
/// scrolls away with the page. A layout with no top bar keeps the bare bar that
/// opens its drawer in view. The [footer] closes the scrolling body
/// ([CruftFreeLayoutBody.footer]).
class CruftFreeShellScaffold extends StatefulWidget {
  const CruftFreeShellScaffold({super.key, required this.idiom, required this.groups, required this.body, this.sidebar, this.topBar, this.topBarFullWidth = false, this.topBarSticky = false, this.sidebarBreakpoint, this.collapsed, this.navBarFrom, this.footer = const <Widget>[]});

  final CruftFreeNavIdiom idiom;
  final List<CruftFreeNavGroup> groups;
  final Widget body;
  final List<Widget> footer;
  final Widget? sidebar;
  final List<Widget>? topBar;
  final bool topBarFullWidth;
  final bool topBarSticky;
  final double? sidebarBreakpoint;
  final PersistedValue<bool>? collapsed;
  final double? navBarFrom;

  @override
  State<CruftFreeShellScaffold> createState() => _CruftFreeShellScaffoldState();
}

class _CruftFreeShellScaffoldState extends State<CruftFreeShellScaffold> {
  static const double _expandedWidth = 256;
  static const double _collapsedWidth = 64;

  List<CruftFreeNavEntry> get _shown => [
    for (final group in widget.groups)
      for (final entry in group.entries)
        if (entry.visible) entry,
  ];

  /// Whether the app bar draws the nav: its `nav;` sits in the top bar and the window is wide enough.
  bool _navInBar(BuildContext context) {
    final from = widget.navBarFrom;
    return from != null && MediaQuery.sizeOf(context).width >= from;
  }

  /// The space that puts the app bar's content on the content column: half of what the window
  /// is wider than the column, none under `fullWidth` or on a window the column fills.
  double _columnInset(BuildContext context) {
    if (widget.topBarFullWidth) {
      return 0;
    }
    final extra = MediaQuery.sizeOf(context).width - CruftFreeTokens.of(context).contentWidth;
    return extra > 0 ? extra / 2 : 0;
  }

  PreferredSizeWidget _appBar(BuildContext context) {
    final children = widget.topBar;
    if (children == null || children.isEmpty) {
      return AppBar();
    }
    final inset = _columnInset(context);
    return AppBar(
      titleSpacing: inset > 0 ? NavigationToolbar.kMiddleSpacing + inset : null,
      title: children.first,
      actions: [
        ...children.sublist(1),
        if (inset > 0) SizedBox(width: inset),
      ],
    );
  }

  /// The app bar, drawing the nav where its [CruftFreeNavBar] sits while [_navInBar] holds.
  PreferredSizeWidget _bar(BuildContext context, String location) {
    final bar = _appBar(context);
    if (!_navInBar(context)) {
      return bar;
    }
    return PreferredSize(
      preferredSize: bar.preferredSize,
      child: _CruftFreeNavBarScope(groups: widget.groups, location: location, child: bar),
    );
  }

  /// Whether *bar* stays in view: the layout's top bar when it is `sticky`, and the bare bar that
  /// opens the drawer of a layout with no top bar.
  bool get _barStays => widget.topBar == null || widget.topBarSticky;

  /// The scaffold's `appBar`: *bar* while it stays in view, none while it scrolls with the page.
  PreferredSizeWidget? _scaffoldBar(PreferredSizeWidget? bar) => _barStays ? bar : null;

  /// The layout's scrolling body, holding *bar* at its top while it scrolls with the page.
  Widget _scrollingBody(PreferredSizeWidget? bar) => CruftFreeLayoutBody(scrollingBar: _barStays ? null : bar, footer: widget.footer, child: widget.body);

  List<Widget> _navRows(BuildContext context, String location, _NavRows mode) {
    return _navInBar(context) ? const <Widget>[] : _entries(context, widget.groups, location, mode);
  }

  Widget _persistent(BuildContext context, Widget sidebar, String location) {
    final collapsed = widget.collapsed;
    final isCollapsed = collapsed != null && collapsed.value;
    final localizations = MaterialLocalizations.of(context);
    final panel = ListView(
      children: [
        if (collapsed != null)
          Align(
            alignment: AlignmentDirectional.centerEnd,
            child: IconButton(icon: Icon(isCollapsed ? Icons.chevron_right : Icons.chevron_left), tooltip: isCollapsed ? localizations.collapsedIconTapHint : localizations.expandedIconTapHint, onPressed: () => setState(() => collapsed.value = !collapsed.value)),
          ),
        if (!isCollapsed) sidebar,
        ..._navRows(context, location, isCollapsed ? _NavRows.collapsed : _NavRows.panel),
      ],
    );
    final bar = widget.topBar == null ? null : _bar(context, location);
    return Scaffold(
      appBar: _scaffoldBar(bar),
      body: Row(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          SizedBox(
            width: isCollapsed ? _collapsedWidth : _expandedWidth,
            child: SafeArea(child: panel),
          ),
          const VerticalDivider(width: 1),
          Expanded(child: _scrollingBody(bar)),
        ],
      ),
    );
  }

  Widget _drawer(BuildContext context, Widget? sidebar, String location) {
    final rows = _navRows(context, location, _NavRows.drawer);
    final bar = _bar(context, location);
    return Scaffold(
      appBar: _scaffoldBar(bar),
      drawer: Drawer(
        child: SafeArea(child: ListView(children: [?sidebar, ...rows])),
      ),
      body: _scrollingBody(bar),
    );
  }

  /// A layout without a sidebar whose app bar draws the nav: no drawer repeats it.
  Widget _barOnly(BuildContext context, String location) {
    final bar = _bar(context, location);
    return Scaffold(appBar: _scaffoldBar(bar), body: _scrollingBody(bar));
  }

  Widget _bottomBar(BuildContext context, List<CruftFreeNavEntry> shown, String location) {
    final bar = widget.topBar == null ? null : _appBar(context);
    return Scaffold(appBar: _scaffoldBar(bar), body: _scrollingBody(bar), bottomNavigationBar: _bottomNavigation(context, shown, location));
  }

  @override
  Widget build(BuildContext context) {
    final location = GoRouter.of(context).routeInformationProvider.value.uri.path;
    final sidebar = widget.sidebar;
    final breakpoint = widget.sidebarBreakpoint;
    if (sidebar == null || breakpoint == null) {
      if (_navInBar(context)) {
        return _barOnly(context, location);
      }
      final shown = _shown;
      if (widget.idiom == CruftFreeNavIdiom.bottomBar && _fitsBottomBar(shown)) {
        return _bottomBar(context, shown, location);
      }
      return _drawer(context, null, location);
    }
    // The window's width, the same width the web target's media rule tests.
    return MediaQuery.sizeOf(context).width >= breakpoint ? _persistent(context, sidebar, location) : _drawer(context, sidebar, location);
  }
}

/// [pages] laid out in the app's print medium and drawn inside the boundary the print capture
/// reads (`Ui.printedPage`): every page an app shows sits under it. The theme the pages read has
/// its text roles and card radius at the width [context] lays out in, where the app's theme makes
/// them follow it ([CruftFreeTokens.themed]), so a resize redraws them with no new build.
Widget cruftfreePrintablePages(BuildContext context, CruftFreeRuntime runtime, Widget? pages) {
  final printable = CruftFreePrintMedium(
    printing: runtime.ui.printMedium,
    child: RepaintBoundary(key: runtime.ui.printBoundary, child: pages),
  );
  final theme = Theme.of(context);
  final themed = theme.extension<CruftFreeTokens>()?.themed;
  return themed == null ? printable : Theme(data: themed(theme, MediaQuery.sizeOf(context).width), child: printable);
}

/// An app's root: its router, its toasts and its theme -- light or dark as
/// the device prefers -- rebuilt when the session's locale changes, its pages
/// printable ([cruftfreePrintablePages]). The app's name on the device is its native
/// project's; the session's brand name, once applied, titles it.
class CruftFreeApp extends StatelessWidget {
  const CruftFreeApp({super.key, required this.runtime, required this.theme, required this.darkTheme});

  final CruftFreeRuntime runtime;
  final ThemeData theme;
  final ThemeData darkTheme;

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: runtime.session,
      builder: (context, _) => MaterialApp.router(title: runtime.brand.name ?? '', routerConfig: runtime.router, scaffoldMessengerKey: runtime.messengerKey, theme: theme, darkTheme: darkTheme, themeMode: ThemeMode.system, builder: (context, pages) => cruftfreePrintablePages(context, runtime, pages)),
    );
  }
}
